package com.collaborativecanvas.client.controller;
import com.collaborativecanvas.client.CollaborativeCanvasClient;import com.collaborativecanvas.client.drawing.*;import com.collaborativecanvas.client.model.*;import com.collaborativecanvas.client.service.*;import com.collaborativecanvas.client.util.FxThread;import com.collaborativecanvas.client.websocket.*;import com.collaborativecanvas.shared.dto.*;import com.collaborativecanvas.shared.enums.*;import com.collaborativecanvas.shared.protocol.WebSocketDestinations;import com.fasterxml.jackson.databind.*;
import javafx.fxml.FXML;import javafx.scene.canvas.Canvas;import javafx.scene.control.*;import javafx.scene.input.Clipboard;import javafx.scene.input.ClipboardContent;import javafx.scene.layout.*;import javafx.scene.paint.Color;import java.util.*;
public class CanvasController {
 @FXML private Canvas drawingCanvas; @FXML private StackPane canvasStack; @FXML private javafx.scene.layout.VBox syncOverlay; @FXML private Label roomIdLabel; @FXML private Label connectionLabel; @FXML private Label statusDot; @FXML private Label statusMessage; @FXML private Label sizeLabel; @FXML private ColorPicker colorPicker; @FXML private Slider sizeSlider; @FXML private ToggleButton brushButton; @FXML private ToggleButton eraserButton; @FXML private Button clearButton; @FXML private ListView<ParticipantViewModel> participants;
 private CollaborativeCanvasClient app;private ClientSession session;private final ObjectMapper json=new ObjectMapper().findAndRegisterModules();private final CanvasRenderer renderer=new CanvasRenderer();private final SpringStompClient stomp=new SpringStompClient();private final ReconnectManager reconnect=new ReconnectManager();private CanvasSyncService sync;private DrawingInputHandler input;private boolean eraser;private String currentParticipantId;
 public void setAppAndSession(CollaborativeCanvasClient app,ClientSession session){this.app=app;this.session=session;colorPicker.setValue(Color.web("#1E88E5"));roomIdLabel.setText(session.roomId());configureParticipantList();sync=new CanvasSyncService(v->requestSync());input=new DrawingInputHandler(drawingCanvas,session.roomId(),this::sendOperation);configureCanvasLayout();drawingCanvas.widthProperty().addListener((o,a,b)->render());drawingCanvas.heightProperty().addListener((o,a,b)->render());sizeSlider.valueProperty().addListener((o,a,b)->{sizeLabel.setText(String.format("%.0f px",b.doubleValue()));updateTool();});colorPicker.valueProperty().addListener((o,a,b)->updateTool());brushButton.setSelected(true);updateTool();setStatus(ConnectionStatus.CONNECTING,"Connecting and synchronizing canvas…");connect();}
 private void configureParticipantList(){participants.setCellFactory(list->new ListCell<>(){private final HBox row=new HBox(9);private final StackPane avatar=new StackPane();private final Label initial=new Label();private final VBox details=new VBox(2);private final Label name=new Label();private final Label role=new Label();private final Label you=new Label("YOU");{avatar.getStyleClass().add("participant-avatar");initial.getStyleClass().add("participant-initial");avatar.getChildren().add(initial);name.getStyleClass().add("participant-name");role.getStyleClass().add("participant-role");details.getChildren().addAll(name,role);you.getStyleClass().add("participant-you");Pane spacer=new Pane();HBox.setHgrow(spacer,Priority.ALWAYS);row.setAlignment(javafx.geometry.Pos.CENTER_LEFT);row.getStyleClass().add("participant-row");row.getChildren().addAll(avatar,details,spacer,you);}@Override protected void updateItem(ParticipantViewModel item,boolean empty){super.updateItem(item,empty);if(empty||item==null){setGraphic(null);return;}String display=item.displayName();initial.setText(display.isBlank()?"?":display.substring(0,1).toUpperCase(Locale.ROOT));name.setText(display);role.setText(item.currentUser()?"You are connected":"Connected");you.setVisible(item.currentUser());you.setManaged(item.currentUser());if(item.currentUser()&&!avatar.getStyleClass().contains("self"))avatar.getStyleClass().add("self");if(!item.currentUser())avatar.getStyleClass().remove("self");setGraphic(row);}});}
 /** The canvas is intentionally unmanaged so it cannot contribute to the preferred size of the panel it follows. */
 private void configureCanvasLayout(){canvasStack.setMinSize(0,0);drawingCanvas.setManaged(false);drawingCanvas.relocate(0,0);drawingCanvas.widthProperty().bind(canvasStack.widthProperty());drawingCanvas.heightProperty().bind(canvasStack.heightProperty());}
 private void connect(){stomp.connect(session.serverUrl(),new StompEventListener(){public void onConnected(){FxThread.run(()->{setStatus(ConnectionStatus.CONNECTING,"Loading shared canvas…");stomp.subscribeRoom(session.roomId());stomp.send(WebSocketDestinations.join(session.roomId()),new JoinRoomRequest(session.displayName()));});}public void onMessage(String raw){FxThread.run(()->receive(raw));}public void onDisconnected(Throwable e){FxThread.run(()->{setStatus(ConnectionStatus.RECONNECTING,"Connection lost. Reconnecting…");reconnect.retry(CanvasController.this::connect);});}});}
 private void receive(String raw){try{JsonNode root=json.readTree(raw);if(root.has("code")){String message=root.path("message").asText("Server error");String code=root.path("code").asText();if("ROOM_NOT_FOUND".equals(code)||"ROOM_EXPIRED".equals(code))setStatus(ConnectionStatus.DISCONNECTED,message);else statusMessage.setText(message);return;}if(root.has("type")&&"CANVAS_STATE".equals(root.path("type").asText())){CanvasStateMessage state=json.treeToValue(root,CanvasStateMessage.class);if(sync.state(state)){currentParticipantId=state.participantId();render();reconnect.connected();setStatus(ConnectionStatus.CONNECTED,"Canvas synchronized.");}else{setStatus(ConnectionStatus.CONNECTING,"Canvas state was incomplete. Retrying…");requestSync();}return;}if(root.has("sequenceNumber")){sync.receive(json.treeToValue(root,DrawingOperationMessage.class));render();return;}if(root.isArray()){List<ParticipantViewModel> rows=new ArrayList<>();for(JsonNode n:root){ParticipantDto p=json.treeToValue(n,ParticipantDto.class);rows.add(new ParticipantViewModel(p.displayName(),p.participantId().equals(currentParticipantId)));}participants.getItems().setAll(rows);}}catch(Exception e){setStatus(ConnectionStatus.CONNECTING,"Could not synchronize canvas. Retrying…");requestSync();}}
 private void sendOperation(DrawingOperationMessage op){if(!stomp.connected()||sync==null)return;try{stomp.send(WebSocketDestinations.operations(session.roomId()),op);}catch(Exception e){statusMessage.setText("Drawing will resume when reconnected.");}}
 private void requestSync(){if(stomp.connected())try{stomp.send(WebSocketDestinations.sync(session.roomId()),Map.of());}catch(Exception ignored){}}
 private void render(){if(sync!=null&&drawingCanvas.getWidth()>0&&drawingCanvas.getHeight()>0)renderer.render(drawingCanvas,sync.document());}
 private void updateTool(){if(input!=null)input.setTool(eraser,"#"+colorPicker.getValue().toString().substring(2,8).toUpperCase(),sizeSlider.getValue());}
 @FXML private void brush(){eraser=false;brushButton.setSelected(true);eraserButton.setSelected(false);updateTool();}
 @FXML private void eraser(){eraser=true;eraserButton.setSelected(true);brushButton.setSelected(false);updateTool();}
 @FXML private void presetBlue(){colorPicker.setValue(Color.web("#1E88E5"));brush();}
 @FXML private void presetBlack(){colorPicker.setValue(Color.web("#15233A"));brush();}
 @FXML private void clear(){Alert a=new Alert(Alert.AlertType.CONFIRMATION,"Clear the shared canvas for everyone in this room?",ButtonType.CANCEL,ButtonType.OK);a.setHeaderText("Clear canvas?");a.showAndWait().filter(b->b==ButtonType.OK).ifPresent(b->sendOperation(new DrawingOperationMessage(UUID.randomUUID(),session.roomId(),null,DrawingOperationType.CLEAR_CANVAS,null,0,0,"#000000",1,false,null,java.time.Instant.now(),null)));}
 @FXML private void copyId(){ClipboardContent c=new ClipboardContent();c.putString(session.roomId());Clipboard.getSystemClipboard().setContent(c);statusMessage.setText("Room ID copied.");}
 @FXML private void leave(){if(stomp.connected())try{stomp.send(WebSocketDestinations.leave(session.roomId()),Map.of());}catch(Exception ignored){}stomp.disconnect();reconnect.close();app.showHome();}
 private void setStatus(ConnectionStatus s,String message){String statusClass=s.name().toLowerCase();connectionLabel.setText(s.name().substring(0,1)+s.name().substring(1).toLowerCase());connectionLabel.getStyleClass().removeAll("connecting","connected","reconnecting","disconnected");connectionLabel.getStyleClass().add(statusClass);statusDot.getStyleClass().removeAll("connecting","connected","reconnecting","disconnected");statusDot.getStyleClass().add(statusClass);statusMessage.setText(message);boolean ready=s==ConnectionStatus.CONNECTED;drawingCanvas.setDisable(!ready);syncOverlay.setVisible(!ready);syncOverlay.setManaged(!ready);}
}
